  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Building a Budget$j$, $j${"readings": [{"title": "Proverbs 21 (King James Version)", "url": "/portal/bible/Proverbs/21"}], "body": "A budget is a plan for your money. It tells every dollar where to go before the month begins. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A budget is how a steward counts the cost.\n\nThe basic idea is simple: income minus expenses. If expenses are greater than income, the budget has a deficit and the person goes into debt or runs out. If income is greater than expenses, there is a surplus that can be saved, given or invested. The goal is a plan in which the numbers balance.\n\nStart by listing income. Use take home pay, not gross pay, and include gifts and part time work. Then list expenses in two groups. Fixed expenses stay about the same each month, such as rent, a car payment or insurance. Variable expenses change, such as food, gas, clothing and entertainment. Add giving and saving as expenses too, and place them near the top of the list.\n\nA popular guideline is the 50, 30, 20 plan. About half of take home pay goes to needs, about thirty percent to wants, and about twenty percent to saving and paying down debt. Giving can be placed first, with the other percentages adjusted. It is a starting point and not a law. Families in high cost areas may need more for housing, and students may have very different numbers. A zero based budget gives every dollar a job so that income minus planned spending equals zero.\n\nReview the budget every month. Compare planned amounts with actual spending and adjust. Involve your family, since a budget works best when everyone understands it. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness.\n\nYour task: (1) Define budget, deficit and surplus. (2) Give three fixed and three variable expenses. (3) Build a sample monthly budget for a part time worker earning 400 dollars.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A budget is how a steward counts the cost.\n\nNow watch this. A budget is a plan for every dollar. Income minus expenses. If expenses are larger, you have a deficit. If income is larger, you have a surplus.\n\nList income using take home pay. Then list expenses. Fixed expenses stay the same, like rent or insurance. Variable expenses change, like food, gas and fun. Put giving and saving near the top.\n\nA guideline is 50, 30, 20. Half to needs, thirty percent to wants and twenty percent to saving and debt. It is a starting point, not a law. A zero based budget gives every dollar a job.\n\nReview every month. Compare planned and actual and adjust. Involve your family.\n\nYour task is to define budget terms, list fixed and variable expenses and build a sample budget. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Building a Budget$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Tracking Spending and Keeping Records$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "A budget only works when it is compared with real spending. Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. In our day, knowing the state of your flocks means knowing where your money goes.\n\nTracking spending can be done in many ways. You can write purchases in a notebook, use a spreadsheet, use a bank or budgeting app, or use envelopes of cash for categories such as food and fun. Pick a method you will actually use. Many people are surprised to learn how small daily purchases add up. A four dollar drink each school day costs about seven hundred dollars in a school year.\n\nRecords protect you. Keep receipts for large purchases and returns, warranties for products, and bank statements for review. Keep tax records, such as Forms W2 and 1099, for as long as advised by the Internal Revenue Service or your tax preparer. Keep important papers in a safe place, such as a locked box or secure digital folder, with a backup. Important papers include a birth certificate, Social Security card, insurance policies, titles, contracts and wills. Keep sensitive documents private.\n\nA personal balance sheet measures your wealth at one moment. Assets are things you own that have value, such as savings, a car or equipment. Liabilities are what you owe, such as loans or credit card balances. Net worth equals assets minus liabilities. A young person may have low or even negative net worth because of student loans, and the goal is for it to grow over time.\n\nMake a monthly money meeting. Sit down for thirty minutes to check balances, pay bills on time, update the budget and set the next steps. Pay bills before their due dates to avoid late fees.\n\nYour task: (1) Describe two ways to track spending. (2) List five records that should be kept. (3) Define asset, liability and net worth.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. Today that means knowing where your money goes.\n\nNow watch this. Track spending in a notebook, a spreadsheet, an app or cash envelopes. Pick what you will use. Small purchases add up. A four dollar drink each school day costs about seven hundred dollars in a school year.\n\nKeep records. Keep receipts for big purchases, warranties and bank statements. Keep tax forms such as the W2 and 1099 as advised. Store important papers safely, like a birth certificate, Social Security card, insurance policies, titles and contracts. Keep sensitive papers private.\n\nA balance sheet shows wealth at one moment. Assets are what you own. Liabilities are what you owe. Net worth is assets minus liabilities. It may start low, and the goal is growth.\n\nHold a monthly money meeting. Check balances, pay bills on time and adjust the budget.\n\nYour task is to describe tracking methods, list records and define net worth. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Tracking Spending and Keeping Records$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Saving and the Emergency Fund$j$, $j${"readings": [{"title": "Proverbs 6 (King James Version)", "url": "/portal/bible/Proverbs/6"}], "body": "Saving is setting aside money now for use later. Proverbs 6:6 to 8 sends us to a small teacher: Go to the ant, thou sluggard; consider her ways, and be wise: Which having no guide, overseer, or ruler, Provideth her meat in the summer, and gathereth her food in the harvest. Proverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up.\n\nJoseph provides a larger example. In Genesis 41:36 he advised Pharaoh, And that food shall be for store to the land against the seven years of famine, which shall be in the land of Egypt; that the land perish not through the famine. Saving in good times protected a nation in hard times.\n\nThere are three main reasons to save. First, for emergencies, such as a medical bill, a car repair or a lost job. Second, for planned goals, such as a car, school or a trip. Third, for the long term, such as retirement. An emergency fund is money kept in a safe, easy to reach account for unexpected needs. A common guideline is to build a small starter fund first, such as one thousand dollars, and then work toward three to six months of basic living expenses.\n\nThe best way to save is to pay yourself first. Move money to savings as soon as you are paid, before you spend it, preferably by an automatic transfer. Small amounts add up, and starting early matters because of compound interest, which we study later. Keep savings in an insured account at a bank or credit union, not under the mattress. Use separate accounts or labels for different goals so that you can see progress.\n\nResist the urge to use the emergency fund for wants such as sales. If you use it, refill it.\n\nYour task: (1) Give three reasons to save. (2) Explain pay yourself first. (3) Set a savings plan for a one thousand dollar starter emergency fund.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 6:6 to 8 says, Go to the ant, thou sluggard; consider her ways, and be wise: Which having no guide, overseer, or ruler, Provideth her meat in the summer, and gathereth her food in the harvest. The ant saves in good times.\n\nNow watch this. Joseph told Pharaoh in Genesis 41:36 that food should be for store against the seven years of famine. Saving in good times protected a nation.\n\nSave for emergencies, for planned goals and for the long term. An emergency fund is money in a safe, reachable account. Start with a starter fund, like one thousand dollars, then build toward three to six months of basic expenses.\n\nPay yourself first. Move money to savings as soon as you are paid, ideally by an automatic transfer. Start early because of compound interest. Keep savings in an insured account. Use separate labels for different goals.\n\nDo not use the emergency fund for sales. If you use it, refill it.\n\nYour task is to give reasons to save, explain pay yourself first and make a plan for a starter fund. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Saving and the Emergency Fund$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Giving, Tithes and Generosity$j$, $j${"readings": [{"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}], "body": "Giving is a central part of Christian stewardship. Deuteronomy 8:18 says, But thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth. Because God is the source, we honor Him with what He gives. Proverbs 3:9 and 10 say, Honour the LORD with thy substance, and with the firstfruits of all thine increase: So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.\n\nThe tithe, which means a tenth, is taught in the Law. Malachi 3:10 says, Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it. Many churches teach the tithe as the starting place of giving, and offerings go beyond it. A believer who tithes places it in the budget first, as firstfruits, instead of giving what is left over.\n\nThe spirit of giving matters as much as the amount. 2 Corinthians 9:7 says, Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver. Plan your giving ahead of time and give with joy.\n\nGod also calls us to care for those in need. Proverbs 19:17 says, He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again. Ephesians 4:28 says we labour that we may have to give to him that needeth. Giving can include time, skills and food as well as money.\n\nWise giving also checks where gifts go. Give to your local church and to trusted ministries and charities. Be careful of appeals that pressure you or promise riches. Keep records of gifts for your own accounting, and ask the church or charity for a receipt for tax purposes where it applies.\n\nYour task: (1) Define tithe and firstfruits. (2) Explain what 2 Corinthians 9:7 says about the attitude of giving. (3) Describe how you will include giving in your budget.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 3:9 and 10 say, Honour the LORD with thy substance, and with the firstfruits of all thine increase: So shall thy barns be filled with plenty. Deuteronomy 8:18 reminds us that it is God who giveth thee power to get wealth.\n\nNow watch this. The tithe means a tenth. Malachi 3:10 says, Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith. Many churches teach the tithe as the starting place of giving, and offerings go beyond it. Give from the first, not from what is left.\n\nAttitude matters. 2 Corinthians 9:7 says, Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver. Plan ahead and give with joy.\n\nCare for the needy. Proverbs 19:17 says, He that hath pity upon the poor lendeth unto the LORD. Giving includes time, skills and food.\n\nBe wise. Give to your church and trusted ministries. Beware of pressure and promises of riches. Keep records and ask for receipts.\n\nYour task is to define tithe and firstfruits, explain cheerful giving and plan giving in your budget. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Giving, Tithes and Generosity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Budgeting, Saving and Giving$j$, $j${"prompt": "Write a report of at least 250 words, with sample work, on budgeting, saving and giving. Use complete sentences and label each part. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nPart 1: Define budget, deficit, surplus, fixed expense and variable expense. Build a monthly budget for a part time worker who takes home 500 dollars, including giving and saving, and show that income minus expenses equals zero.\nPart 2: Describe a method for tracking spending that you would use. List five records that should be kept and where you would keep them.\nPart 3: Define asset, liability and net worth, and calculate net worth for someone with 1,200 dollars in assets and 400 dollars in liabilities.\nPart 4: Explain why an emergency fund matters, what pay yourself first means, and make a savings plan for a 1,000 dollar starter fund. Use Proverbs 6:6 to 8 or Genesis 41:36.\nPart 5: Define tithe and firstfruits, explain 2 Corinthians 9:7, and describe how you will give wisely.", "rubric": "100 points. Part 1: 25 points. Part 2: 15 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Budgeting, Saving and Giving$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Counting the Cost and Giving with Joy$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when planning ahead helped you or someone you know, (2) explains in your own words why a budget helps a steward, (3) explains how a person can save and give at the same time, and (4) connects your answer to Luke 14:28, Proverbs 6:6 to 8, Malachi 3:10 or 2 Corinthians 9:7. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What is one small spending habit you could change to save more? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Counting the Cost and Giving with Joy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Building a Budget$j$, $j${"questions": [{"q": "When spending is greater than income, the budget has a:", "options": ["Profit", "Surplus", "Deficit", "Refund"]}, {"q": "Rent is usually an example of a:", "options": ["Variable expense", "Fixed expense", "Tax credit", "Income"]}, {"q": "In the 50, 30, 20 guideline, about 50 percent goes to:", "options": ["Entertainment", "Gifts only", "Wants", "Needs"]}, {"q": "A budget should be built from:", "options": ["Gross pay only", "Borrowed money", "Take home pay", "Guesses about lottery wins"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Building a Budget$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,2}'::int[], array[$j$A deficit means spending exceeds income.$j$,$j$Rent stays about the same each month.$j$,$j$Half of take home pay goes to needs.$j$,$j$Use the amount you actually receive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Building a Budget$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Tracking Spending and Keeping Records$j$, $j${"questions": [{"q": "Things you own that have value are called:", "options": ["Assets", "Expenses", "Liabilities", "Deductions"]}, {"q": "Money that you owe is a:", "options": ["Surplus", "Liability", "Refund", "Asset"]}, {"q": "Net worth is calculated as:", "options": ["Assets plus liabilities", "Assets minus liabilities", "Income plus tax", "Gross pay minus net pay"]}, {"q": "Proverbs 27:23 encourages a person to:", "options": ["Hide his money", "Ignore his finances", "Know the state of his flocks", "Borrow freely"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Tracking Spending and Keeping Records$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,2}'::int[], array[$j$Assets are valuable things you own.$j$,$j$A liability is a debt or obligation.$j$,$j$Subtract what you owe from what you own.$j$,$j$Be diligent to know your financial condition.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Tracking Spending and Keeping Records$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Saving and the Emergency Fund$j$, $j${"questions": [{"q": "Money set aside for unexpected needs is an:", "options": ["Expense account", "Tax return", "Credit line", "Emergency fund"]}, {"q": "Paying yourself first means:", "options": ["Moving money to savings when you are paid", "Skipping savings", "Spending before paying bills", "Taking a loan"]}, {"q": "Who saved food in good years against a famine in Genesis 41?", "options": ["Moses", "Gideon", "Samson", "Joseph"]}, {"q": "A common long term goal for the emergency fund is:", "options": ["Ten years of income", "Three to six months of basic expenses", "One day of pay", "No savings"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Saving and the Emergency Fund$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,1}'::int[], array[$j$An emergency fund covers surprises.$j$,$j$Save before you spend.$j$,$j$Joseph advised storing food.$j$,$j$That range is a widely used guideline.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Saving and the Emergency Fund$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Giving, Tithes and Generosity$j$, $j${"questions": [{"q": "The word tithe means:", "options": ["A half", "A hundredth", "A tenth", "A fifth"]}, {"q": "2 Corinthians 9:7 says God loves:", "options": ["A secret hoarder", "A silent giver", "A reluctant giver", "A cheerful giver"]}, {"q": "Giving the first part of increase to God is called giving:", "options": ["Firstfruits", "Change", "Leftovers", "Interest"]}, {"q": "Wise giving includes:", "options": ["Giving only what is left", "Giving to trusted churches and charities and keeping records", "Never planning gifts", "Giving under pressure to anyone"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Giving, Tithes and Generosity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,1}'::int[], array[$j$A tithe is one tenth.$j$,$j$God values a joyful heart.$j$,$j$Firstfruits honor God first.$j$,$j$Be planned and careful.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Giving, Tithes and Generosity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Budgeting, Saving and Giving$j$, $j${"questions": [{"q": "A plan that tells your money where to go is a:", "options": ["Budget", "Tax return", "Receipt", "Loan"]}, {"q": "A car payment that stays the same each month is a:", "options": ["Asset", "Fixed expense", "Gift", "Variable expense"]}, {"q": "Assets minus liabilities equals:", "options": ["Gross pay", "Interest", "Deficit", "Net worth"]}, {"q": "An emergency fund is meant for:", "options": ["Sales and wants", "Entertainment", "Unexpected needs", "Gifts only"]}, {"q": "The best way to build savings is to:", "options": ["Save what is left, if any", "Wait until you are older", "Borrow to save", "Pay yourself first by automatic transfer"]}, {"q": "Proverbs 6:6 sends the sluggard to learn from:", "options": ["The ox", "The ant", "The eagle", "The lion"]}, {"q": "The tithe is:", "options": ["A tenth", "A bonus", "A twentieth", "A half"]}, {"q": "2 Corinthians 9:7 teaches that giving should be:", "options": ["Cheerful and purposed in the heart", "Hidden from God", "Forced", "Grudging"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Budgeting, Saving and Giving$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,2,3,1,0,0}'::int[], array[$j$That is the purpose of a budget.$j$,$j$Payments that do not change are fixed.$j$,$j$That is the definition of net worth.$j$,$j$It covers surprises like repairs or lost work.$j$,$j$Saving first makes it happen.$j$,$j$The ant gathers food in the harvest.$j$,$j$Tithe means tenth.$j$,$j$God loves a cheerful giver.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Budgeting, Saving and Giving$j$ on conflict (item_id) do nothing;
